57	// container mount, or folded under HOME.
58	func shortPath(path, root string) string {
59		for _, base := range []string{root, scanMount} {
60			switch {
61			case base == "":
62			case path == base:
63				return "."
64			case strings.HasPrefix(path, base+"/"):
65				if rest := strings.TrimLeft(path[len(base):], "/"); rest != "" {
66					return rest
67				}
68				return "."
69			}
70		}
71		return theme.FoldHome(path)
72	}
73	
74	// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
75	// It measures with x/ansi, as the viewport does, not with runewidth.
76	func oneLine(text string, width int) string {
77		if width <= 0 {
78			return ""
79		}
80		first, _, _ := strings.Cut(text, "\n")
81		first = strings.TrimSuffix(first, "\r")
82		if ansi.StringWidth(first) <= width {
83			return first
84		}
85		return ansi.Truncate(first, width, theme.Ellipsis)
86	}
87	
88	// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
89	// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
90	// lines left out. A blank text gives nil, 0.
91	func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
92		if strings.TrimSpace(text) == "" {
93			return nil, 0
94		}
95		text = strings.TrimRight(text, " \t\r\n")
96		lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
97		if len(lines) > maxLines {
98			return lines[:maxLines], len(lines) - maxLines
99		}
100		return lines, 0
101	}
102	
103	// moreLines is the marker after a capped text, "" when nothing was left out.
104	func moreLines(n int) string {
105		switch {
106		case n <= 0:
107			return ""
108		case n == 1:
109			return "… 1 more line"
110		}
111		return fmt.Sprintf("… %d more lines", n)
112	}
113	
114	// scrollPosition is "Lines a-b of N" when the content is taller than the
115	// viewport, "" otherwise.
116	func scrollPosition(offset, visible, total int) string {
117		if visible <= 0 || total <= visible {
118			return ""
119		}
120		offset = max(offset, 0)
121		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
122	}
