638	// The details pane is a scrollable viewport, and a long finding is the normal
639	// case — a description plus references routinely runs past the terminal.
640	func TestTheDetailsPaneScrolls(t *testing.T) {
641		tall := detailsModel(t)
642		tall.detailsViewport.SetHeight(10)
643		tall.detailsViewport.SetContent(strings.Repeat("a line of the description\n", 40))
644	
645		for _, tc := range []struct {
646			name string
647			keys []string
648			want int
649		}{
650			{"down moves one line", []string{"down"}, 1},
651			{"back up returns to the top", []string{"down", "down", "up", "up"}, 0},
652			{"a half page moves further than a line", []string{"pgdown"}, 5},
653			{"end goes to the bottom", []string{"end"}, tall.detailsViewport.TotalLineCount() - 10},
654			{"home comes back", []string{"end", "home"}, 0},
655		} {
656			t.Run(tc.name, func(t *testing.T) {
657				m := feed(t, tall, testutil.Keys(tc.keys...)...)
658	
659				if got := m.detailsViewport.YOffset(); got != tc.want {
660					t.Errorf("offset = %d after %v, want %d", got, tc.keys, tc.want)
661				}
662				if m.state != StateDetails {
663					t.Errorf("scrolling left the details for %v", m.state)
664				}
665			})
666		}
667	}
